#!/usr/bin/env node
// Writes apps/web/ios/App/App/Info-Dev.plist: Info.plist plus the `logbook` URL scheme.
//
// The release Info.plist registers no URL scheme, because nothing in the release build uses one (App Review Guideline
// 2.5.19: what is not offered is not in the binary). The owner's own development build still has Strava, and Strava's
// sign-in comes back to the app through logbook://settings. So the Debug configuration of the Xcode project reads this
// generated file instead. `pnpm ios` and `pnpm ios:fresh` run this script after `npx cap sync ios`. The file is not
// committed (apps/web/ios/.gitignore), like the other files that sync writes.
//
// Never edit Info-Dev.plist: change Info.plist and run this again.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const app = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', 'apps', 'web', 'ios', 'App', 'App');

const SCHEME = `	<key>CFBundleURLTypes</key>
	<array>
		<dict>
			<key>CFBundleURLName</key>
			<string>$(PRODUCT_BUNDLE_IDENTIFIER)</string>
			<key>CFBundleURLSchemes</key>
			<array>
				<string>logbook</string>
			</array>
		</dict>
	</array>
`;

/** Info.plist's text with the URL scheme added as the last key and a note that the file is generated. */
export const devPlist = (release) => {
  if (release.includes('CFBundleURLTypes')) throw new Error('Info.plist already registers a URL scheme. The release plist must not.');
  const end = release.lastIndexOf('</dict>');
  const head = release.indexOf('<plist');
  if (end < 0 || head < 0) throw new Error('Info.plist does not look like a property list');
  const note = '<!-- Generated by scripts/ios-dev-plist.mjs from Info.plist for Debug builds only. Do not edit: change Info.plist and run pnpm ios. -->\n';
  return release.slice(0, head) + note + release.slice(head, end) + SCHEME + release.slice(end);
};

const isMain = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  fs.writeFileSync(path.join(app, 'Info-Dev.plist'), devPlist(fs.readFileSync(path.join(app, 'Info.plist'), 'utf8')));
  console.log('Wrote apps/web/ios/App/App/Info-Dev.plist (Debug builds: Info.plist plus the logbook URL scheme)');
}
